import html
from datetime import datetime, timedelta, timezone
from urllib.parse import urlencode

import httpx
from fastapi import APIRouter
from fastapi.responses import HTMLResponse
from jose import jwt

from app.core.config import settings
from app.db.session import SessionLocal
from app.models.company import Company
from app.models.instagram_account import InstagramAccount

# Public router (no app-wide auth): Instagram redirects the browser here. The
# signed `state` is what ties the callback to a company, and it only comes
# from a link generated by an admin (see scripts/instagram_connect_link.py).
router = APIRouter(prefix="/instagram/oauth", tags=["Instagram OAuth"])

SCOPES = ",".join(
    [
        "instagram_business_basic",
        "instagram_business_content_publish",
        "instagram_business_manage_comments",
        "instagram_business_manage_messages",
    ]
)
STATE_TTL = timedelta(minutes=60)
STATE_PURPOSE = "ig_connect"


def redirect_uri() -> str:
    return f"{settings.PUBLIC_BASE_URL}/instagram/oauth/callback"


def build_connect_url(company_id: int) -> str:
    state = jwt.encode(
        {
            "cid": company_id,
            "purpose": STATE_PURPOSE,
            "exp": datetime.now(timezone.utc) + STATE_TTL,
        },
        settings.JWT_SECRET_KEY,
        algorithm=settings.JWT_ALGORITHM,
    )
    params = {
        "client_id": settings.INSTAGRAM_APP_ID,
        "redirect_uri": redirect_uri(),
        "response_type": "code",
        "scope": SCOPES,
        "state": state,
        # Log in again so the right account can be picked even if the browser
        # is already signed in to a different one.
        "force_reauth": "true",
    }
    return "https://www.instagram.com/oauth/authorize?" + urlencode(params)


def _page(ok: bool, title: str, text: str) -> HTMLResponse:
    color = "#1f6b63" if ok else "#a33a2a"
    body = f"""<!doctype html><html lang="ru"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(title)}</title></head>
<body style="font-family:system-ui,sans-serif;max-width:480px;margin:12vh auto;padding:0 20px;color:#171a18">
<h1 style="font-size:1.4rem;color:{color}">{html.escape(title)}</h1>
<p style="line-height:1.5">{html.escape(text)}</p></body></html>"""
    return HTMLResponse(body, status_code=200 if ok else 400)


@router.get("/callback", response_class=HTMLResponse)
def oauth_callback(
    code: str | None = None,
    state: str | None = None,
    error: str | None = None,
    error_description: str | None = None,
):
    if error:
        return _page(False, "Подключение отменено", error_description or error)

    try:
        payload = jwt.decode(state or "", settings.JWT_SECRET_KEY, algorithms=[settings.JWT_ALGORITHM])
        if payload.get("purpose") != STATE_PURPOSE:
            raise ValueError("wrong purpose")
        company_id = int(payload["cid"])
    except Exception:
        return _page(False, "Ссылка недействительна", "Ссылка устарела или повреждена. Запросите новую.")

    if not code:
        return _page(False, "Нет кода авторизации", "Instagram не вернул код. Попробуйте ещё раз по новой ссылке.")
    code = code.split("#_")[0]

    try:
        short_resp = httpx.post(
            "https://api.instagram.com/oauth/access_token",
            data={
                "client_id": settings.INSTAGRAM_APP_ID,
                "client_secret": settings.INSTAGRAM_APP_SECRET,
                "grant_type": "authorization_code",
                "redirect_uri": redirect_uri(),
                "code": code,
            },
            timeout=20,
        )
        short_data = short_resp.json()
        entry = short_data["data"][0] if "data" in short_data else short_data
        short_token = entry["access_token"]

        long_data = httpx.get(
            "https://graph.instagram.com/access_token",
            params={
                "grant_type": "ig_exchange_token",
                "client_secret": settings.INSTAGRAM_APP_SECRET,
                "access_token": short_token,
            },
            timeout=20,
        ).json()
        token = long_data["access_token"]

        me = httpx.get(
            "https://graph.instagram.com/me",
            params={"fields": "user_id,username", "access_token": token},
            timeout=20,
        ).json()
        account_id = str(me.get("user_id") or me["id"])
        username = me.get("username")
    except Exception as exc:
        # Log only the exception type: response bodies/tokens must not reach logs.
        print(f"Instagram OAuth exchange failed for company {company_id}: {type(exc).__name__}")
        return _page(
            False,
            "Не удалось подключить аккаунт",
            "Instagram не принял код. Убедитесь, что аккаунт добавлен в приложение как тестер "
            "и что адрес возврата добавлен в настройках приложения Meta, затем запросите новую ссылку.",
        )

    db = SessionLocal()
    try:
        company = db.query(Company).filter(Company.id == company_id).first()
        if company is None:
            return _page(False, "Компания не найдена", "Запросите новую ссылку.")

        now = datetime.utcnow()
        account = db.query(InstagramAccount).filter(InstagramAccount.company_id == company_id).first()
        if account is None:
            account = InstagramAccount(company_id=company_id, account_id=account_id, access_token=token)
            db.add(account)
        account.account_id = account_id
        account.username = username
        account.access_token = token
        account.token_refreshed_at = now
        account.last_refresh_attempt_at = None
        db.commit()
        company_name = company.name
    finally:
        db.close()

    handle = f"@{username}" if username else "аккаунт"
    return _page(True, "Instagram подключён", f"{handle} подключён к проекту «{company_name}». Окно можно закрыть.")
